import BalanceInformations from "./components/BalanceInformations";
import Header from "./components/Header";
import Main from "./components/Main";
import ActionsSection from "./components/Actions";
import BalanceActions from "./components/BalanceActions";
import LoansActions from "./components/LoansActions";
import AccountActions from "./components/AccountActions";
import { useReducer } from "react";

const initalState = {
  isAccountOpen: false,
  balance: 0,
  loan: 0,
  AccountActionLogs: [],
};

function reducer(state, action) {
  switch (action.type) {
    case "openAccount":
      return { ...state, isAccountOpen: true };
    case "deposit":
      return { ...state, balance: state.balance + action.payload };
    case "withdrawal":
      return { ...state, balance: state.balance + action.payload };
    case "getLoan":
      return { ...state, balance: state.balance + action };
    default:
      throw new Error("Unknown reducer action");
  }
}

function App() {
  const [state, dispatch] = useReducer(reducer, initalState);

  return (
    <div className="app">
      <Header />
      <Main>
        <BalanceInformations
          balance={state.balance}
          loanBalance={state.loanBalance}
        />
        <ActionsSection>
          <BalanceActions />
          <LoansActions />
          <AccountActions />
        </ActionsSection>
      </Main>
    </div>
  );
}

export default App;
